        Movies::create(
        ['title' => `U2: Vertigo 2005 - Live from Chicago`,
        'content' => `Le Vertigo Tour de U2 a été lancé en mars 2005 pour accompagner son dernier album studio, How to Dismantle an Atomic Bomb , dont le single " Vertigo " a donné son titre à la tournée. La tournée a traversé cinq étapes différentes et s'est terminée par un dernier concert à Honolulu le 9 décembre 2006.  Les deux concerts présentés sur Vertigo 2005: Live from Chicago ont été enregistrés et interprétés au United Center de Chicago du 9 au 10 mai 2005.`,
        'img' => `https://image.tmdb.org/t/p/w500/x3VVcnPSp54IZQGy9nzzSb7SQkL.jpg`
        ]); 
        Movies::create(
        ['title' => `Tu as l’étoffe d’un champion, Charlie Brown`,
        'content' => `Peppermint Patty et Charlie Brown participent à une course de motocross où ils seront mis à mal par des obstacles, de la boue et le Vengeur masqué.`,
        'img' => `https://image.tmdb.org/t/p/w500/wSi3Xh3daiKU0jYPrdansdoOEZF.jpg`
